CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE account_role AS ENUM ('WORKER','EMPLOYER','AGENCY','ADMIN'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE application_status AS ENUM ('DRAFT','READY','SUBMITTED','REVIEW','SHORTLISTED','INTERVIEW','OFFER','VISA','TRAVEL','HIRED','REJECTED','WITHDRAWN'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES users(id) ON DELETE CASCADE, email text UNIQUE NOT NULL, password_hash text NOT NULL, role account_role NOT NULL, phone text, email_verified_at timestamptz, last_login_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS worker_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, headline text, bio text, country text, city text, years_experience int DEFAULT 0, availability text, relocation_ready boolean DEFAULT false, skills jsonb NOT NULL DEFAULT '[]', languages jsonb NOT NULL DEFAULT '[]', rating numeric(3,2), created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id uuid REFERENCES users(id), org_type text NOT NULL CHECK(org_type IN ('EMPLOYER','AGENCY')), name text NOT NULL, legal_name text, description text, country text, city text, address text, website text, verified boolean DEFAULT false, verification_data jsonb NOT NULL DEFAULT '{}', created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS organization_members (organization_id uuid REFERENCES organizations(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'MEMBER', PRIMARY KEY(organization_id,user_id));
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, title text NOT NULL, description text, category text NOT NULL, country text NOT NULL, city text NOT NULL, lat numeric(10,7), lng numeric(10,7), employment_type text, salary_min numeric, salary_max numeric, salary_currency text DEFAULT 'EUR', accommodation boolean DEFAULT false, transport boolean DEFAULT false, language_requirements jsonb DEFAULT '[]', visa_status text, work_permit_required boolean DEFAULT true, requirements jsonb NOT NULL DEFAULT '{}', required_documents jsonb NOT NULL DEFAULT '[]', proof_requirements jsonb NOT NULL DEFAULT '{}', status text DEFAULT 'OPEN', created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS jobs_geo_idx ON jobs(lat,lng); CREATE INDEX IF NOT EXISTS jobs_country_city_idx ON jobs(country,city); 
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, document_type text NOT NULL, title text NOT NULL, storage_key text, status text DEFAULT 'UPLOADED', expires_at timestamptz, verified boolean DEFAULT false, metadata jsonb DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS proof_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, title text NOT NULL, description text, media_url text, evidence_id uuid REFERENCES media_evidence(id), skill_tags jsonb DEFAULT '[]', verified boolean DEFAULT false, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id), worker_user_id uuid NOT NULL REFERENCES users(id), agency_id uuid REFERENCES organizations(id), status application_status DEFAULT 'DRAFT', readiness_score int DEFAULT 0, missing_documents jsonb DEFAULT '[]', notes text, submitted_at timestamptz, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), UNIQUE(job_id,worker_user_id));
CREATE TABLE IF NOT EXISTS application_documents (application_id uuid REFERENCES applications(id) ON DELETE CASCADE, document_id uuid REFERENCES documents(id), required boolean DEFAULT true, PRIMARY KEY(application_id,document_id));
CREATE TABLE IF NOT EXISTS interviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid UNIQUE REFERENCES applications(id) ON DELETE CASCADE, scheduled_at timestamptz, meeting_url text, status text DEFAULT 'SCHEDULED', notes text);
CREATE TABLE IF NOT EXISTS offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid UNIQUE REFERENCES applications(id) ON DELETE CASCADE, salary numeric, currency text, start_date date, accommodation boolean, transport boolean, terms jsonb DEFAULT '{}', status text DEFAULT 'PENDING', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS relocation_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid UNIQUE REFERENCES applications(id) ON DELETE CASCADE, current_country text, current_city text, target_country text, target_city text, work_permit_status text DEFAULT 'NOT_STARTED', visa_status text DEFAULT 'NOT_STARTED', travel_status text DEFAULT 'NOT_STARTED', arrival_status text DEFAULT 'NOT_STARTED', checklist jsonb DEFAULT '{}', updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS conversation_members (conversation_id uuid REFERENCES conversations(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid REFERENCES conversations(id) ON DELETE CASCADE, sender_user_id uuid REFERENCES users(id), body text NOT NULL, created_at timestamptz DEFAULT now(), read_at timestamptz);
CREATE TABLE IF NOT EXISTS requirement_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country text NOT NULL, job_category text, title text NOT NULL, source_url text, authority text, requirements jsonb NOT NULL DEFAULT '{}', updated_at timestamptz DEFAULT now());
INSERT INTO users(public_id,display_name) VALUES('WP-DEMO-WORKER','Demo Worker') ON CONFLICT(public_id) DO NOTHING;
INSERT INTO organizations(owner_user_id,org_type,name,description,country,city,verified) SELECT u.id,'EMPLOYER','NordSteel GmbH','Steel fabrication and manufacturing','Germany','Dortmund',true FROM users u WHERE u.public_id='GR-USER-DEV' AND NOT EXISTS(SELECT 1 FROM organizations WHERE name='NordSteel GmbH');
INSERT INTO jobs(organization_id,title,description,category,country,city,lat,lng,employment_type,salary_min,salary_max,accommodation,transport,visa_status,requirements,required_documents) SELECT o.id,'Industrial Welder','MIG/MAG welding in a modern steel production facility.','Welding','Germany','Dortmund',51.5136,7.4653,'FULL_TIME',2900,3500,true,true,'Employer supports work permit process','{"experienceYears":2,"languages":["English","German preferred"],"qualifications":["Welding certificate"]}','["Passport","CV","Welding certificate","Work certificate"]'::jsonb FROM organizations o WHERE o.name='NordSteel GmbH' AND NOT EXISTS(SELECT 1 FROM jobs WHERE title='Industrial Welder' AND organization_id=o.id);
